using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.FNZ.TiposMovimiento;namespace GraphApi.Services.FNZ.TiposMovimiento{    public class TiposMovimientoService : ITiposMovimientoService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TiposMovimientoService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTiposMovimiento>> GetTiposMovimientos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM fnz.TiposMovimiento (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTiposMovimiento>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTiposMovimientosDynamic(            int? tipoMovimientoID,            string? tipoMovimiento,            bool? bCargo,            bool? bAbono,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoMovimientoID, TipoMovimiento, bCargo, bAbono, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM fnz.TiposMovimiento (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoMovimientoID.HasValue)            {                vSql.Append(" AND TipoMovimientoID = @TipoMovimientoID");                vParameters.Add("TipoMovimientoID",tipoMovimientoID);            }            if (!string.IsNullOrWhiteSpace(tipoMovimiento))            {                vSql.Append(" AND TipoMovimiento LIKE @TipoMovimiento");                vParameters.Add("TipoMovimiento",$"%{tipoMovimiento}%");            }            if (bCargo.HasValue)            {                vSql.Append(" AND bCargo = @bCargo");                vParameters.Add("bCargo", bCargo.Value);            }            if (bAbono.HasValue)            {                vSql.Append(" AND bAbono = @bAbono");                vParameters.Add("bAbono", bAbono.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTiposMovimiento> CreateTiposMovimiento(clCreateTiposMovimiento objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO fnz.TiposMovimiento                (TipoMovimiento, bCargo, bAbono, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoMovimiento, @bCargo, @bAbono, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoMovimiento,                objInput.bCargo,                objInput.bAbono,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoMovimientoID, TipoMovimiento, bCargo, bAbono, bEliminado                FROM fnz.TiposMovimiento (NOLOCK)                WHERE TipoMovimientoID = @TipoMovimientoID;";            var vReadParams = new { TipoMovimientoID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTiposMovimiento>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TiposMovimiento con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTiposMovimiento?> UpdateTiposMovimiento(clUpdateTiposMovimiento objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoMovimientoID", objInput.TipoMovimientoID);            if (objInput.TipoMovimiento is not null)            {                vSets.Add("TipoMovimiento = @TipoMovimiento");                vParameters.Add("TipoMovimiento", objInput.TipoMovimiento);            }            if (objInput.bCargo != null)            {                vSets.Add("bCargo = @bCargo");                vParameters.Add("bCargo", objInput.bCargo);            }            if (objInput.bAbono != null)            {                vSets.Add("bAbono = @bAbono");                vParameters.Add("bAbono", objInput.bAbono);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE fnz.TiposMovimiento                SET {vSetClause}                WHERE TipoMovimientoID = @TipoMovimientoID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoMovimientoID, TipoMovimiento, bCargo, bAbono, bEliminado                FROM fnz.TiposMovimiento (NOLOCK)                WHERE TipoMovimientoID = @TipoMovimientoID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTiposMovimiento>(sSelect, new {  objInput.TipoMovimientoID });        }        public async Task<bool> DeleteTiposMovimiento(int nTiposMovimientoID)        {            const string sSql = @"                DELETE FROM fnz.TiposMovimiento                WHERE TipoMovimientoID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTiposMovimientoID });            return vAffected > 0;        }    }}